"""Unified local workspace shell; clinical intake uses the same-origin service."""
from __future__ import annotations

import json

from .ui_tokens import TOKENS


def render_clinical_workspace(*, synthetic_preview: bool = False,
                              teaching_provenance: dict | None = None,
                              exact_rx_teaching: bool = False) -> str:
    """Keep incumbent pages isolated and embed only presentation provenance."""
    if type(synthetic_preview) is not bool:
        raise ValueError("SYNTHETIC_PREVIEW_BOOLEAN_REQUIRED")
    if type(exact_rx_teaching) is not bool:
        raise ValueError("EXACT_RX_TEACHING_BOOLEAN_REQUIRED")
    if teaching_provenance is not None and not isinstance(teaching_provenance, dict):
        raise ValueError("TEACHING_PROVENANCE_OBJECT_REQUIRED")
    payload = json.dumps({"synthetic_preview": synthetic_preview,
                          "exact_rx_teaching": exact_rx_teaching,
                          "teaching_provenance": teaching_provenance},
                         ensure_ascii=True, sort_keys=True, allow_nan=False,
                         separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return HTML.replace("__CSS__", CSS).replace("__JS__", JS).replace("__DATA__", payload)


